#!/usr/bin/env python3
# Writes tests/cli_b/<unit>.rs: one test per recorded case on each door, one per help page.
import json, re
D = "/root/wsp-vm/wt-2449-cli-b/host/crates/wsp-cli/tests"
UNITS = ["activity", "slate", "projects", "computers", "agents_skills", "agents_servers", "workspaces_git", "workspaces_life"]

def snake(s):
    s = re.sub(r"[^a-z0-9]+", "_", s.lower()).strip("_")
    return s if not s[0].isdigit() else "n" + s

for u in UNITS:
    d = json.load(open(f"{D}/fixtures/cli_b/{u}.json"))
    pages = json.load(open(f"{D}/fixtures/cli_b/{u}.pages.json"))
    seen = {}
    out = [f"// SPDX-License-Identifier: AGPL-3.0-only\n// Generated by tests/fixtures/cli_b/record/gentests.py from {u}.json and {u}.pages.json: each recorded case\n// held on the command line (text and --json) and, for a tool's case, on the tool door; each verb's help page.\n\nuse crate::common::{{case, holds, page_holds, tool_holds}};\n"]
    def name(base):
        n = snake(base)[:80].rstrip("_")
        seen[n] = seen.get(n, 0) + 1
        return n if seen[n] == 1 else f"{n}_{seen[n]}"
    for c in d["cases"]:
        tool = c.get("tool") or "hand"
        lit = json.dumps(c["case"], ensure_ascii=False)
        n = name(f"{tool} {c['case']}")
        out.append(f"#[test]\nfn line_{n}() {{\n    holds(&case({json.dumps(u)}, {json.dumps(tool)}, {lit}));\n}}\n")
        if tool != "hand" and c.get("tool_result") is not None:
            out.append(f"#[test]\nfn tool_{n}() {{\n    tool_holds(&case({json.dumps(u)}, {json.dumps(tool)}, {lit}));\n}}\n")
    for key in pages:
        mode, verb = key.split(" ", 1)
        if "error" in pages[key]:
            continue
        out.append(f"#[test]\nfn page_{mode}_{snake(verb)}() {{\n    page_holds({json.dumps(u)}, {json.dumps(verb)}, {'true' if mode == 'cloud' else 'false'});\n}}\n")
    open(f"{D}/cli_b/{u}.rs", "w").write("\n".join(out))
    print(u, sum(1 for l in out if l.startswith("#[test]")))
